import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_ORDER = Pattern.compile("^[a-zA-Z_]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        // Validate sort column against allowlist pattern
        if (sortCol != null && !SAFE_ORDER.matcher(sortCol).matches()) {
            resp.sendError(400, "Invalid sort column");
            return;
        }

        // Build report query based on type
        String baseQuery;
        switch (reportType != null ? reportType : "summary") {
            case "detailed":
                baseQuery = "SELECT id, account_name, txn_date, amount, category FROM transactions";
                break;
            case "aggregated":
                baseQuery = "SELECT category, SUM(amount) as total, COUNT(*) as cnt FROM transactions";
                break;
            default:
                baseQuery = "SELECT txn_date, SUM(amount) as daily_total FROM transactions";
                break;
        }

        // Apply date range filter using parameterized approach
        StringBuilder query = new StringBuilder(baseQuery);
        query.append(" WHERE txn_date BETWEEN ? AND ?");

        // Apply custom filter expression - allows power users to add conditions
        if (filterExpr != null && !filterExpr.isEmpty()) {
            // Sanitize: remove comments and semicolons
            String cleaned = filterExpr.replaceAll("--.*", "").replaceAll(";", "");
            // Additional check: reject if it contains certain keywords
            String upper = cleaned.toUpperCase();
            if (upper.contains("DROP") || upper.contains("ALTER") || 
                upper.contains("TRUNCATE") || upper.contains("INSERT") ||
                upper.contains("UPDATE") || upper.contains("DELETE") ||
                upper.contains("EXEC")) {
                resp.sendError(400, "Forbidden keyword in filter");
                return;
            }
            query.append(" AND (").append(cleaned).append(")");
        }

        // Apply grouping for aggregated reports
        if ("aggregated".equals(reportType)) {
            query.append(" GROUP BY category");
        } else if ("summary".equals(reportType) || reportType == null) {
            query.append(" GROUP BY txn_date");
        }

        // Apply sort
        if (sortCol != null) {
            query.append(" ORDER BY ").append(sortCol);
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(query.toString())) {

            stmt.setString(1, dateFrom != null ? dateFrom : "2024-01-01");
            stmt.setString(2, dateTo != null ? dateTo : "2024-12-31");

            ResultSet rs = stmt.executeQuery();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnLabel(i) + "\": ");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            resp.sendError(500, "Query failed: " + e.getMessage());
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }
}
